style.css:
@-moz-document domain("youtube.com") {
/* ==========================================================================
       1. CHOOSE YOUR BACKGROUND IMAGES HERE!
       ========================================================================== */
    :root {
        /* Change the URLs inside the quotes to your favorite Sailor Moon wallpapers */
        --sailor-main-bg: url("https://i.pinimg.com/1200x/ad/01/6a/ad016a6b5ac8d3c840d3434f30c258be.jpg"); /* Starry space base background */
        --sailor-overlay: rgba(255, 230, 240, 0.88); /* Translucent pastel pink sheet over your background for readability */
        
        /* Pastel Magical Palette */
        --sailor-pink: #ff79c6 !important;       /* Main Magical Pink Accent */
        --sailor-yellow: #f1fa8c !important;     /* Moonlight Gold Accent */
        --sailor-purple: #bd93f9 !important;     /* Deep Pastel Purple Text */
        --sailor-dark-text: #4b2354 !important;  /* High contrast readable text */
    }

    /* ==========================================================================
       2. APPLYING THE THEME (LIGHT MODE BASE HIGHLY RECOMMENDED)
       ========================================================================== */
    html, body, ytd-app {
        background-image: var(--sailor-main-bg) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Make YouTube containers translucent so the background shows through */
    ytd-page-manager, 
    #contentContainer.ytd-app, 
    #columns.ytd-watch-flexy, 
    ytd-browse, 
    ytd-guide-renderer,
    #masthead-container.ytd-app,
    ytd-masthead {
        background: transparent !important;
    }

    /* Add the readable pastel pink overlay panels */
    ytd-rich-grid-renderer, 
    #secondary.ytd-watch-flexy, 
    #watch7-sidebar,
    #content-text,
    ytd-playlist-panel-renderer {
        background-color: var(--sailor-overlay) !important;
        border-radius: 16px !important;
        padding: 15px !important;
        backdrop-filter: blur(4px) !important; /* Elegant glassmorphism effect */
    }

    /* Top Navigation Bar */
    #background.ytd-masthead {
        background: rgba(255, 200, 220, 0.9) !important;
        border-bottom: 2px solid var(--sailor-pink) !important;
    }

    /* ==========================================================================
       3. TEXT AND SPECIFIC PROPERTIES
       ========================================================================== */
    html, [theme="light"] {
        /* Swap system variables to match Sailor Moon colors */
        --yt-spec-base-background: transparent !important;
        --yt-spec-text-primary: var(--sailor-dark-text) !important;
        --yt-spec-text-secondary: var(--sailor-purple) !important;
        --yt-spec-brand-red: var(--sailor-pink) !important;
        --yt-spec-static-brand-red: var(--sailor-pink) !important;
        --yt-spec-call-to-action: var(--sailor-pink) !important;
        
        /* Video progress bar and loading elements */
        --yt-spec-static-brand-background-solid: var(--sailor-pink) !important;
    }

    /* ==========================================================================
       4. MAGICAL AESTHETIC DETAILS
       ========================================================================== */
    
    /* Round off thumbnails and add a soft pink aura on hover */
    ytd-thumbnail img, ytd-thumbnail {
        border-radius: 12px !important;
        transition: all 0.3s ease-in-out !important;
    }
    
    ytd-rich-item-renderer:hover ytd-thumbnail img {
        box-shadow: 0 0 15px rgba(255, 121, 198, 0.7) !important;
        transform: scale(1.02);
    }

    /* Magical Sailor Moon heart/moon shape for the search bar */
    #container.ytd-searchbox {
        background-color: white !important;
        border: 2px solid var(--sailor-pink) !important;
        border-radius: 20px 0 0 20px !important;
    }
    
    #search-icon-legacy.ytd-searchbox {
        background-color: var(--sailor-pink) !important;
        border: 2px solid var(--sailor-pink) !important;
        border-radius: 0 20px 20px 0 !important;
    }
    
    #search-icon-legacy.ytd-searchbox yt-icon {
        color: white !important;
    }

    /* Custom Scrollbar */
    ::-webkit-scrollbar {
        width: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: rgba(255, 230, 240, 0.5) !important;
    }
    ::-webkit-scrollbar-thumb {
        background: var(--sailor-pink) !important;
        border-radius: 5px !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: var(--sailor-yellow) !important;
    }
}
